 text("ROAD "+(level+1)+"   SPEED "+(int)(speed*20)+"   TIME "+time(elapsed),w*.03f,h*.07f,h*.035f,-1);rect(w*.03f,h*.09f,w*.30f,h*.105f,0xff333344);rect(w*.03f,h*.09f,w*(.03f+.27f*Math.min(1,pos/length())),h*.105f,0xff64caa1);
